from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta


@dataclass
class Shipment:
    id: str
    carrier: str
    eta: datetime  # loaded from a timestamptz column


def _naive_utc(dt: datetime) -> datetime:
    return dt.replace(tzinfo=None) if dt.tzinfo else dt


def is_overdue(shipment: Shipment, now: datetime | None = None) -> bool:
    now = now or datetime.utcnow()
    return _naive_utc(shipment.eta) < now


def time_left(shipment: Shipment, now: datetime | None = None) -> timedelta:
    now = now or datetime.utcnow()
    return max(_naive_utc(shipment.eta) - now, timedelta(0))

