"""Validation for user-uploaded images before they are queued for thumbnailing."""

import imghdr
from dataclasses import dataclass

MAX_BYTES = 15 * 1024 * 1024
ALLOWED = {"jpeg", "png", "gif", "webp"}


class UploadRejected(ValueError):
    pass


@dataclass(frozen=True)
class CheckedUpload:
    filename: str
    kind: str
    size: int


def validate_upload(filename: str, data: bytes) -> CheckedUpload:
    if not data:
        raise UploadRejected("empty file")
    if len(data) > MAX_BYTES:
        raise UploadRejected(f"file too large ({len(data)} bytes, max {MAX_BYTES})")

    # Trust the content, not the extension.
    kind = imghdr.what(None, h=data[:32])
    if kind not in ALLOWED:
        raise UploadRejected(f"unsupported image type: {kind or 'unknown'}")
    return CheckedUpload(filename=filename, kind=kind, size=len(data))

