import click
from tabulate import tabulate

from tasklog.store import Store, default_db_path


@click.group()
@click.option("--db", type=click.Path(path_type=Path), default=default_db_path, show_default=True)
@click.pass_context
def cli(ctx: click.Context, db: Path) -> None:
    """Track time per client."""
    ctx.obj = Store(db)


@cli.command()
@click.argument("client")
@click.argument("minutes", type=click.IntRange(min=1))
@click.option("-m", "--message", default="")
@click.pass_obj
def log(store: Store, client: str, minutes: int, message: str) -> None:
    """Log MINUTES of work for CLIENT."""
    store.add(client=client, minutes=minutes, message=message, day=dt.date.today())


@cli.command()
@click.option("--since", type=click.DateTime(formats=["%Y-%m-%d"]), help="First day to include.")
@click.option("--client", help="Only this client.")
@click.pass_obj
def report(store: Store, since: dt.datetime | None, client: str | None) -> None:
    """Hours per client and day."""
    rows = store.summary(since=since.date() if since else None, client=client)
    if not rows:
        click.echo("nothing logged")
        return
    table = [(r.day.isoformat(), r.client, f"{r.minutes / 60:.2f}") for r in rows]
    click.echo(tabulate(table, headers=["day", "client", "hours"]))

