from datetime import date, timedelta

from leavedesk.holidays import is_holiday


def add_business_days(start: date, days: int) -> date:
    """Move forward `days` working days. The start day itself never counts."""
    current = start
    while days > 0:
        current += timedelta(days=1)
        if current.weekday() < 5 and not is_holiday(current):
            days -= 1
    return current


def due_date(submitted: date | None = None, business_days: int = 2) -> date:
    """Managers must answer a leave request within `business_days` working days."""
    return add_business_days(submitted or date.today(), business_days)

