from datetime import date, timedelta
from functools import cache


def _easter(year: int) -> date:
    # Anonymous Gregorian algorithm
    a, b, c = year % 19, year // 100, year % 100
    d, e = b // 4, b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = c // 4, c % 4
    l = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l) // 451
    month, day = divmod(h + l - 7 * m + 114, 31)
    return date(year, month, day + 1)


@cache
def holidays(year: int) -> frozenset[date]:
    e = _easter(year)
    fixed = {date(year, 1, 1), date(year, 5, 1), date(year, 10, 3), date(year, 12, 25), date(year, 12, 26)}
    moving = {e - timedelta(days=2), e + timedelta(days=1), e + timedelta(days=39), e + timedelta(days=50)}
    return frozenset(fixed | moving)


def is_holiday(day: date) -> bool:
    return day in holidays(day.year)

import aiohttp

API = {
    "brettspielhaus": "https://api.brettspielhaus.example/v2/products/{sku}",
    "meeplemarkt": "https://meeplemarkt.example/api/price?sku={sku}",
}


async def fetch_price(shop: str, sku: str) -> float | None:
    session = aiohttp.ClientSession()
    async with session.get(API[shop].format(sku=sku)) as resp:
        if resp.status == 404:
