from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass
from pathlib import Path

from deadlinks.extract import iter_links
from deadlinks.http import probe


@dataclass(frozen=True)
class BrokenLink:
    url: str
    source: Path
    status: int


def check_site(site_dir: Path, *, timeout: float, external: bool) -> list[BrokenLink]:
    broken = []
    for source, url in iter_links(site_dir):
        if not external and url.startswith(("http://", "https://")):
            continue
        status = probe(url, site_dir=site_dir, timeout=timeout)
        if status >= 400:
            broken.append(BrokenLink(url, source, status))
    return broken

from concurrent.futures import ProcessPoolExecutor

from gcscan.fasta import read_fasta
from gcscan.stats import gc_stats


def run_serial(paths, min_len):
    return {path: gc_stats(read_fasta(path), min_len) for path in paths}


def run(paths, min_len, workers=None):
    # workers=None -> one process per CPU core

    def analyse(path):
        return path, gc_stats(read_fasta(path), min_len)

    with ProcessPoolExecutor(max_workers=workers) as pool:
        # map() sends each path to a worker process

        return dict(pool.map(analyse, paths))
